using System;using System.IO;using System.Drawing;using System.Diagnostics;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;using NAudio.Wave;
namespace Captura {
 static class ProfileTests {
  static string Run(string file,string args){using(var p=new Process{StartInfo=new ProcessStartInfo(file,args){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true}}){p.Start();var read=p.StandardOutput.ReadToEndAsync();var err=p.StandardError.ReadToEndAsync();if(!p.WaitForExit(60000)){p.Kill();throw new Exception("Probe expirou");}if(p.ExitCode!=0)throw new Exception(err.Result);return read.Result;}}
  static void Tone(string path){using(var w=new WaveFileWriter(path,new WaveFormat(48000,16,1))){byte[] b=new byte[48000*2*4];for(int i=0;i<b.Length/2;i++){short n=(short)(Math.Sin(i*2*Math.PI*440/48000)*3000);b[i*2]=(byte)n;b[i*2+1]=(byte)(n>>8);}w.Write(b,0,b.Length);}}
  public static void Execute(){string root=AppDomain.CurrentDomain.BaseDirectory,dir=Path.Combine(root,"profiles-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")),log=Path.Combine(root,"profile-test.txt");Directory.CreateDirectory(dir);File.WriteAllText(log,"");using(var host=new Form{Text="Priint profile fixture",ClientSize=new Size(640,360),Location=new Point(70,70),StartPosition=FormStartPosition.Manual,BackColor=Color.Navy}){host.Shown+=async delegate{try{var rect=new Rectangle(host.Left+10,host.Top+40,320,180);await Task.Run(delegate{
   string ff=EncoderLocator.Find(),probe=Path.Combine(Path.GetDirectoryName(ff),"ffprobe.exe");var gpu=VideoProfiles.Encoders();File.AppendAllText(log,"Encoders: "+string.Join(" | ",gpu.ConvertAll(e=>e.ToString()).ToArray())+Environment.NewLine);
   using(var choice=new FpsChoice()){if(choice.Items.Count!=4)throw new Exception("FPS não é seletor fechado");foreach(int rate in VideoProfiles.Rates){choice.Value=rate;if(choice.Value!=rate)throw new Exception("FPS seleção falhou");}}
   bool invalid=false;try{VideoProfiles.Validate(new RecordingRequest{Fps=30,Container="AVI",Codec="H.265"});}catch(ArgumentException){invalid=true;}if(!invalid)throw new Exception("AVI HEVC inválido foi aceito");
   foreach(string name in new[]{"cpu-h264-mp4-mp3","cpu-hevc","gpu-1440","gpu-4k-hevc","avi-mp3","120","240"}){
    bool hardware=name.StartsWith("gpu")||name=="120"||name=="240";if(hardware&&gpu.Count<2){File.AppendAllText(log,name+" SKIP GPU indisponível"+Environment.NewLine);continue;}
    string tone=Path.Combine(dir,name+".wav");bool audio=name.Contains("mp3");if(audio)Tone(tone);
    var req=new RecordingRequest{Mode=RecordingMode.Region,Region=rect,EncoderPath=ff,OutputDirectory=dir,Fps=name=="120"?120:name=="240"?240:name.StartsWith("gpu")?60:30,UseNvenc=hardware,GpuIndex=hardware?gpu[1].Index:0,Codec=name.Contains("hevc")?"H.265":"H.264",Container=name.StartsWith("avi")?"AVI":"MP4",Resolution=name=="gpu-4k-hevc"?"2160p":name=="gpu-1440"?"1440p":name=="cpu-hevc"?"1080p":name=="cpu-h264-mp4-mp3"?"720p":"Original",Quality="Equilibrada",MinMbps=5,MaxMbps=25,SeparateMp3=audio,TestAudioTracks=audio?new[]{tone}:null};
    using(var recorder=new RecordingEngine()){recorder.Start(req);recorder.Ready.GetAwaiter().GetResult();Thread.Sleep(850);if(!recorder.IsRecording)throw new Exception("Primeira gravação parou sozinha");string video=recorder.StopAsync().GetAwaiter().GetResult();string meta=Run(probe,"-v error -select_streams v:0 -show_entries stream=codec_name,width,height,avg_frame_rate -of default=noprint_wrappers=1 "+Args.Q(video));Size size=VideoProfiles.OutputSize(req.Resolution,rect.Size);if(!meta.Contains("codec_name="+(req.Codec=="H.265"?"hevc":"h264"))||!meta.Contains("width="+size.Width)||!meta.Contains("height="+size.Height)||!meta.Contains("avg_frame_rate="+req.Fps+"/1"))throw new Exception("Metadados diferentes do solicitado: "+meta);
      if(audio){string mp3=Path.ChangeExtension(video,".mp3");if(!File.Exists(mp3))throw new Exception("MP3 ausente");string a=Run(probe,"-v error -select_streams a:0 -show_entries stream=codec_name -of default=noprint_wrappers=1 "+Args.Q(mp3));if(!a.Contains("mp3"))throw new Exception("MP3 inválido");}
      File.AppendAllText(log,name+" OK "+recorder.PerformanceSummary+" "+Path.GetFileName(video)+Environment.NewLine);
    }
   }
   using(var repeated=new RecordingEngine()){for(int n=0;n<3;n++){repeated.Start(new RecordingRequest{Mode=RecordingMode.Region,Region=rect,EncoderPath=ff,OutputDirectory=dir,Fps=30});repeated.Ready.GetAwaiter().GetResult();Thread.Sleep(500);if(!repeated.IsRecording)throw new Exception("Encerrou sem solicitação");repeated.StopAsync().GetAwaiter().GetResult();}File.AppendAllText(log,"3 inícios/paradas na mesma instância: OK"+Environment.NewLine);}
   File.AppendAllText(log,"OK profiles, codecs, resolutions, FPS, MP3, CPU/GPU e reinicialização."+Environment.NewLine);
  });}catch(Exception ex){File.AppendAllText(log,"FAIL "+ex+Environment.NewLine);Environment.ExitCode=1;}finally{host.Close();}};host.ShowDialog();}}
 }
}

